GRIMOIRE_BY_KEY = {}
for _, entry in ipairs( GRIMOIRE ) do GRIMOIRE_BY_KEY[entry.key] = entry end

-- An entry's strokes: { { { x = , y = }, ... }, ... } on the Spellbook's page (180 x 180, the ring around 90, 90);
-- the other books scale them to their pages
local DIGITS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local VALUE = {}
for i = 1, #DIGITS do VALUE[DIGITS:sub( i, i )] = i - 1 end
function grimoire_strokes( entry )
	if entry.decoded then return entry.decoded end
	local strokes = {}
	for part in entry.strokes:gmatch( "[^|]+" ) do
		local stroke = {}
		for i = 1, #part - 3, 4 do
			local x = VALUE[part:sub( i, i )] * 64 + VALUE[part:sub( i + 1, i + 1 )]
			local y = VALUE[part:sub( i + 2, i + 2 )] * 64 + VALUE[part:sub( i + 3, i + 3 )]
			stroke[#stroke + 1] = { x = x / 10, y = y / 10 }
		end
		if #stroke > 0 then strokes[#strokes + 1] = stroke end
	end
	entry.decoded = strokes
	return strokes
end
